class HomeTabs extends StatefulWidget { @override _HomeTabsState createState() => _HomeTabsState(); }
class _HomeTabsState extends State<HomeTabs> {
  int idx = 0;
  final tabs = [BodyProTab(), ClothesTab(), MakeupTab(), HairTab(), BackgroundTab(), RetouchProTab()];
  @override Widget build(BuildContext context) {
    return Scaffold(
      body: tabs[idx],
      bottomNavigationBar: BottomNavigationBar(currentIndex: idx, onTap: (i)=>setState(()=>idx=i), type: BottomNavigationBarType.fixed, selectedItemColor: Colors.pinkAccent, items: [
        BottomNavigationBarItem(icon: Icon(Icons.accessibility_new), label: 'Body'),
        BottomNavigationBarItem(icon: Icon(Icons.checkroom), label: 'Clothes'),
        BottomNavigationBarItem(icon: Icon(Icons.face), label: 'Makeup'),
        BottomNavigationBarItem(icon: Icon(Icons.face_retouching_natural), label: 'Hair'),
        BottomNavigationBarItem(icon: Icon(Icons.wallpaper), label: 'Bg'),
        BottomNavigationBarItem(icon: Icon(Icons.auto_fix_high), label: 'Retouch'),
      ]),
    );
  }
}
Future<Uint8List?> aiEdit({required File original, required String prompt}) async {
  final url = Uri.parse('https://image.pollinations.ai/prompt/${Uri.encodeComponent(prompt)}?model=flux&nologo=true');
  try { final resp = await http.get(url); if(resp.statusCode==200) return resp.bodyBytes; } catch(e){}
  return null;
}
