  @override Widget build(BuildContext c){ return Scaffold(appBar: AppBar(title: Text('Body Pro'), backgroundColor: Colors.pinkAccent), body: ListView(padding: EdgeInsets.all(16), children:[ElevatedButton(onPressed: pick, child: Text('Subir Foto')), if(img!=null) Image.file(img!, height: 200), Text('Busto $bust'), Slider(value: bust, min: -10, max: 10, onChanged: (v)=>setState(()=>bust=v)), Text('Cintura $waist'), Slider(value: waist, min: -10, max: 10, onChanged: (v)=>setState(()=>waist=v)), Text('Cadera $hip'), Slider(value: hip, min: -10, max: 10, onChanged: (v)=>setState(()=>hip=v)), ElevatedButton(style: ElevatedButton.styleFrom(backgroundColor: Colors.pinkAccent), onPressed: () async { if(img==null) return; setState(()=>load=true); String prompt="Beautiful woman body retouch, bust $bust, waist slim $waist, hip $hip, height $height, slim $weight, keep face identity, photorealistic 8k"; final r=await aiEdit(original: img!, prompt: prompt); setState(()=>{res=r, load=false}); }, child: Text(load?'Procesando...':'APLICAR BODY PRO')), if(res!=null) Image.memory(res!), Paywall()]),); }
}
